module tb_TopModule;
  reg [2:0] y_tb;
  reg w_tb;
  wire Y1_tb;

  TopModule uut (
    .y(y_tb),
    .w(w_tb),
    .Y1(Y1_tb)
  );

  // Independent behavioural model for next-state y[1]
  function reg get_expected_Y1(input [2:0] state, input sw);
    reg [2:0] next_state;
    begin
      case (state)
        3'b000: next_state = (sw == 0) ? 3'b001 : 3'b000; // A -> B or A
        3'b001: next_state = (sw == 0) ? 3'b010 : 3'b011; // B -> C or D
        3'b010: next_state = (sw == 0) ? 3'b100 : 3'b011; // C -> E or D
        3'b011: next_state = (sw == 0) ? 3'b101 : 3'b000; // D -> F or A
        3'b100: next_state = (sw == 0) ? 3'b100 : 3'b011; // E -> E or D
        3'b101: next_state = (sw == 0) ? 3'b010 : 3'b011; // F -> C or D
        default: next_state = 3'b000;
      endcase
      get_expected_Y1 = next_state[1];
    end
  endfunction

  integer s, sw_val;
  reg exp;
  reg [31:0] err_count;

  initial begin
    err_count = 0;
    #10;
    for (s = 0; s < 6; s = s + 1) begin
      for (sw_val = 0; sw_val < 2; sw_val = sw_val + 1) begin
        y_tb = s[2:0];
        w_tb = sw_val[0];
        #10;
        exp = get_expected_Y1(y_tb, w_tb);
        if (Y1_tb !== exp) begin
          $display("FAIL: y=%b, w=%b | got Y1=%b, expected=%b", y_tb, w_tb, Y1_tb, exp);
          err_count = err_count + 1;
        end else begin
          $display("PASS: y=%b, w=%b | Y1=%b", y_tb, w_tb, Y1_tb);
        end
      end
    end

    if (err_count == 0) begin
      $display("SELFTEST PASS");
    end else begin
      $display("SELFTEST FAIL: %0d errors", err_count);
    end
    $finish;
  end

endmodule
